	if len(statuses) == 1 {
		must = append(must, map[string]interface{}{
			"term": map[string]string{"CloseStatus": statusStrs[0]},
		})
	} else {
		must = append(must, map[string]interface{}{
			"terms": map[string]interface{}{"CloseStatus": statusStrs},
		})
	}

	for _, f := range domainFilter {
