			failure_details = EXCLUDED.failure_details,
			history_fetch_error = EXCLUDED.history_fetch_error,
			updated_at = NOW()`,
		failure.TenantID,
		failure.WorkflowID,
		failure.RunID,
		failure.WorkflowType,
		failure.TaskList,
		failure.CloseStatus,
