	case detailLine != "":
		return detailLine
	case trimmedMessage != "":
		return trimmedMessage
	case trimmedReason != "" && !genericFailureReason(trimmedReason):
		return trimmedReason
	case trimmedFetchError != "":
		return trimmedFetchError
	case trimmedReason != "":
		return trimmedReason
	default:
		return status
	}
}

