            {sorted.map((tl, idx) => {
              const encodedName = encodeURIComponent(tl.tasklist);
              const tileId = `tasklist-latency:${encodedName}`;
              const tileLabel = `Tasklist: ${tl.tasklist}`;
              const isActive = activeAlerts && activeAlerts.has(tileId);
              return (
                <tr key={idx}>
